#################################################################
#    Classes: Derivatives
#################################################################

fis:Forward
    a owl:Class ;
    rdfs:label "Forward"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [
                a owl:Restriction ;
                owl:onProperty fis:hasStandardizedTerms ;
                owl:hasValue false
            ]
        )
    ] ;
    rdfs:subClassOf fis:Derivative .

fis:Future
    a owl:Class ;
    rdfs:label "Future"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [
                a owl:Restriction ;
                owl:onProperty fis:hasClearingHouse ;
                owl:someValuesFrom fis:ClearingHouse
            ]
            [
                a owl:Restriction ;
                owl:onProperty fis:hasStandardizedTerms ;
                owl:hasValue true
            ]
        )
    ] ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:comment "Standardized forward contract traded on an exchange with fulfillment guaranteed by a clearing house."@en .

