#################################################################
#    Disjointness Axioms
#################################################################

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:Corporation
        fis:SovereignGovernment
        fis:Municipality
        fis:SupranationalOrganization
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:CorporateBond
        fis:GovernmentBond
        fis:MunicipalBond
        fis:SupranationalBond
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:Forward
        fis:Future
        fis:Option
        fis:Swap
    ) .

fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption owl:disjointWith fis:EuropeanOption .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:BearerCertificate owl:disjointWith fis:RegisteredCertificate .

fis:BearerSecurity owl:disjointWith fis:RegisteredSecurity .

fis:MutualFund owl:disjointWith fis:ExchangeTradedFund .

fis:ResidentialMortgagePool owl:disjointWith fis:CommercialMortgagePool .
